<?php

declare(strict_types=1);namespace Atlas\Platform\PatientResources\Admin;use Atlas\Platform\Core\Logging\Logger;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\PatientResources\Catalog\PatientEducationCatalogRepository;use Atlas\Platform\PatientResources\Domain\BrandingProfile;use Atlas\Platform\PatientResources\Repositories\BrandingRepository;use Atlas\Platform\PatientResources\Repositories\VariantRepository;use Atlas\Platform\PatientResources\Services\PatientResourceVariantService;use Atlas\Platform\Resources\Presentation\StructuredContentRenderer;use Atlas\Platform\Resources\Services\ResourceReader;use Throwable;
final class PatientResourceComposerAdminPage{private string$hook='';public function __construct(private PatientEducationCatalogRepository$catalog,private PatientResourceVariantService$variants,private VariantRepository$variantRepository,private BrandingRepository$branding,private ResourceReader$resources,private StructuredContentRenderer$renderer,private CurrentOrganizationResolver$organizations,private Logger$logger){}public function register():void{$this->hook=(string)add_submenu_page('atlas',__('Patient Resources','atlas-platform'),__('Patient Resources','atlas-platform'),'atlas_manage_branding','atlas-patient-resources',[$this,'render']);}public function enqueue(string$hook):void{if($hook===$this->hook){wp_enqueue_style('atlas-preview',ATLAS_PLATFORM_URL.'assets/css/atlas-preview.css',[],ATLAS_PLATFORM_VERSION);}}public function create():void{$this->guard();check_admin_referer('atlas_create_patient_resource');$organization=$this->organizations->resolveForUser(get_current_user_id());if($organization===null){$this->redirect('context-required');}$selection=sanitize_text_field(wp_unslash((string)($_POST['resource_selection']??'')));[$resource,$version]=array_pad(explode('|',$selection,2),2,'');$allowed=false;foreach($this->catalog->publishedForContext($organization->id)as$item){if($item->resourceId===$resource&&$item->versionId===$version){$allowed=true;break;}}if(!$allowed){$this->redirect('not-found');}$custom=$this->customFromPost();try{$variant=$this->variants->save($organization->id,$version,$custom,sanitize_text_field(wp_unslash((string)($_POST['idempotency_key']??''))),get_current_user_id(),sanitize_text_field(wp_unslash((string)($_POST['variant_name']??''))));if($variant===null){$this->redirect('not-found');}$url=add_query_arg(['page'=>'atlas-patient-resources','atlas_notice'=>$variant->replayed?'restored':'created','variant_id'=>$variant->id,'resource_id'=>$resource],admin_url('admin.php'));}catch(Throwable$failure){$this->logger->log('error','patient_resources.admin_variant_failed','Patient Resource composition failed.',[],'patient_resources',$failure);$url=add_query_arg(['page'=>'atlas-patient-resources','atlas_notice'=>'failed'],admin_url('admin.php'));}wp_safe_redirect($url);exit;}public function update():void{$this->guard();check_admin_referer('atlas_update_patient_resource');$organization=$this->organizations->resolveForUser(get_current_user_id());if($organization===null){$this->redirect('context-required');}$id=sanitize_text_field(wp_unslash((string)($_POST['variant_id']??'')));$variant=$this->variantRepository->findForOrganization($id,$organization->id);if($variant===null){$this->redirect('not-found');}$ok=$this->variants->update($organization->id,$id,$this->customFromPost(),get_current_user_id(),sanitize_text_field(wp_unslash((string)($_POST['variant_name']??''))));$this->redirect($ok?'updated':'failed',$id,$this->resourceIdForVersion($organization->id,$variant->resourceVersionId));}public function archive():void{$this->status('archived','archived');}public function restore():void{$this->status('active','restored');}public function render():void{$this->guard();$organization=$this->organizations->resolveForUser(get_current_user_id());$items=$organization===null?[]:$this->catalog->publishedForContext($organization->id);$notice=sanitize_key(wp_unslash((string)($_GET['atlas_notice']??'')));$variantId=sanitize_text_field(wp_unslash((string)($_GET['variant_id']??'')));$resourceId=sanitize_text_field(wp_unslash((string)($_GET['resource_id']??'')));$variants=$organization===null?[]:$this->variantRepository->listForOrganization($organization->id);$variant=$organization===null||$variantId===''?null:$this->variantRepository->findForOrganization($variantId,$organization->id);$resource=$organization===null||$resourceId===''?null:$this->resources->findPublished($resourceId,$organization->id);if($variant!==null&&($resource===null||$resource->version->id!==$variant->resourceVersionId)){$resourceId=$this->resourceIdForVersion($organization->id,$variant->resourceVersionId);$resource=$resourceId===''?null:$this->resources->findPublished($resourceId,$organization->id);}if($variant!==null&&($resource===null||$resource->version->id!==$variant->resourceVersionId)){$variant=null;$resource=null;}$brand=$organization===null?null:($this->branding->findForOrganization($organization->id)??BrandingProfile::neutral($organization->id,$organization->name));$bodyHtml=$resource===null?'':$this->renderer->render($resource->version->body);$isExport=sanitize_key(wp_unslash((string)($_GET['atlas_export']??'')))==='print';require ATLAS_PLATFORM_DIR.'templates/patient-resources/composer.php';}private function guard():void{if(!current_user_can('atlas_manage_branding')){wp_die(esc_html__('You are not allowed to compose patient resources.','atlas-platform'),'', ['response'=>403]);}}private function customFromPost():array{return['clinic_phone'=>sanitize_text_field(wp_unslash((string)($_POST['clinic_phone']??''))),'clinic_address'=>sanitize_textarea_field(wp_unslash((string)($_POST['clinic_address']??''))),'approved_footer'=>sanitize_textarea_field(wp_unslash((string)($_POST['approved_footer']??'')))];}private function status(string$status,string$notice):void{$this->guard();check_admin_referer('atlas_variant_status');$organization=$this->organizations->resolveForUser(get_current_user_id());if($organization===null){$this->redirect('context-required');}$id=sanitize_text_field(wp_unslash((string)($_POST['variant_id']??'')));$variant=$this->variantRepository->findForOrganization($id,$organization->id);if($variant===null){$this->redirect('not-found');}$ok=$this->variantRepository->setStatus($id,$organization->id,$status,get_current_user_id());$this->redirect($ok?$notice:'failed',$id,$this->resourceIdForVersion($organization->id,$variant->resourceVersionId));}private function resourceIdForVersion(string$organizationId,string$versionId):string{foreach($this->catalog->publishedForContext($organizationId,100)as$item){if($item->versionId===$versionId){return$item->resourceId;}}return'';}private function redirect(string$notice,string$variantId='',string$resourceId=''):never{$args=['page'=>'atlas-patient-resources','atlas_notice'=>$notice];if($variantId!==''){$args['variant_id']=$variantId;}if($resourceId!==''){$args['resource_id']=$resourceId;}wp_safe_redirect(add_query_arg($args,admin_url('admin.php')));exit;}}
